    const auto rule = stack.symbols.back();
    stack.symbols.pop_back();
    for (const auto& sequence : rules_.at(rule)) {
      if (stack.symbols.size() + sequence.size() > kMaxStack)
        throw std::runtime_error("JSON grammar stack limit exceeded");
      auto next = stack;
